INSERT INTO `rule_type_meta` (`rule_type`, `rule_group`, `type_name`, `type_desc`, `doc_code`, `builtin`, `sort_order`) VALUES ('PRODUCT_MULTI_APPROVAL','PRODUCT','商品多层审批','SPU、SKU列表、区域价格列表依次审批；按成本口径计算毛利率','PRODUCT_SKU',0,1);
INSERT INTO `rule_type_field` (`id`, `rule_type`, `field_key`, `field_name`, `field_type`, `required`, `default_value`, `min_value`, `max_value`, `enum_options`, `placeholder`, `sort_order`, `remark`) VALUES (2,'PRODUCT_MULTI_APPROVAL','marginThreshold','毛利率审批阈值（严格大于）','DECIMAL',1,'0.3','0',NULL,NULL,'0.3或30%',1,NULL);
INSERT INTO `rule_definition` (`id`, `rule_group`, `rule_type`, `rule_name`, `rule_params`, `drl_content`, `status`, `version`, `remark`, `create_time`, `update_time`) VALUES (1,'PRODUCT','PRODUCT_MULTI_APPROVAL','PRODUCT_MULTI_APPROVAL_DEFAULT','{\"marginThreshold\":\"0.3\"}','package com.example.drools.dynamic;\n\ndialect \"mvel\"\n\nimport java.util.List;\nimport java.util.ArrayList;\nimport com.example.drools.domain.DocFact;\nimport com.example.drools.domain.DocItem;\n\n\nrule \"PRODUCT_MULTI_APPROVAL_DEFAULT#1 SPU属性审批并赋值1个字段\"\n    salience 95\n    when\n        $d : DocFact( docCode == \"PRODUCT_SKU\", ext[\"PRODUCT_MULTI_APPROVAL_DEFAULT_step1_done\"] == null )\n    then\n        $d.getExt().put(\"PRODUCT_MULTI_APPROVAL_DEFAULT_step1_done\", true);\n        update($d);\n        $d.getExt().put(\"instanceId\", new java.math.BigDecimal($d.getString(\"spu.costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($d.getString(\"spu.salePrice\")).subtract(new java.math.BigDecimal($d.getString(\"spu.costPrice\"))).compareTo(new java.math.BigDecimal($d.getString(\"spu.costPrice\")).multiply(new java.math.BigDecimal(\"0.3\"))) > 0 ? \"T+2\" : \"T\"));\n        $d.getExt().put(\"PRODUCT_MULTI_APPROVAL_DEFAULT_step1_done\", true);\n        update($d);\n        $d.addRuleMessage(\"第1步[SPU属性审批并赋值1个字段]写入 1 个返回字段\");\n    end\n\nrule \"PRODUCT_MULTI_APPROVAL_DEFAULT#2 遍历每个SKU审批并赋值2个字段\"\n    salience 90\n    when\n        $d : DocFact( docCode == \"PRODUCT_SKU\" )\n        $i : DocItem( docCode == \"PRODUCT_SKU\", collection == \"sku\" )\n        eval($i.getExt().get(\"PRODUCT_MULTI_APPROVAL_DEFAULT_step2_done\") == null)\n    then\n        $i.getExt().put(\"instanceId\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).compareTo(new java.math.BigDecimal($i.getString(\"costPrice\")).multiply(new java.math.BigDecimal(\"0.3\"))) > 0 ? \"T+2\" : \"T\"));\n        $i.getExt().put(\"marginRate\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? null : new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).divide(new java.math.BigDecimal($i.getString(\"costPrice\")), 8, 4));\n        $i.getExt().put(\"PRODUCT_MULTI_APPROVAL_DEFAULT_step2_done\", true);\n        update($i);\n        $d.addRuleMessage(\"第2步[遍历每个SKU审批并赋值2个字段]写入 2 个返回字段\");\n    end\n\nrule \"PRODUCT_MULTI_APPROVAL_DEFAULT#3 遍历每个区域价格审批并赋值3个字段\"\n    salience 85\n    when\n        $d : DocFact( docCode == \"PRODUCT_SKU\" )\n        $i : DocItem( docCode == \"PRODUCT_SKU\", collection == \"regionPrice\" )\n        eval($i.getExt().get(\"PRODUCT_MULTI_APPROVAL_DEFAULT_step3_done\") == null)\n    then\n        $i.getExt().put(\"instanceId\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).compareTo(new java.math.BigDecimal($i.getString(\"costPrice\")).multiply(new java.math.BigDecimal(\"0.3\"))) > 0 ? \"T+2\" : \"T\"));\n        $i.getExt().put(\"marginRate\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? null : new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).divide(new java.math.BigDecimal($i.getString(\"costPrice\")), 8, 4));\n        $i.getExt().put(\"priceDecision\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($i.getString(\"salePrice\")).compareTo(new java.math.BigDecimal($i.getString(\"marketPrice\"))) <= 0 ? \"STANDARD\" : \"REVIEW\"));\n        $i.getExt().put(\"PRODUCT_MULTI_APPROVAL_DEFAULT_step3_done\", true);\n        update($i);\n        $d.addRuleMessage(\"第3步[遍历每个区域价格审批并赋值3个字段]写入 3 个返回字段\");\n    end\n\n',1,3,'商品三步审批示例：1/2/3个结果字段','2026-09-30 14:01:44','2026-09-30 14:01:49');
