INSERT INTO `rule_template` (`id`, `rule_type`, `template_body`, `create_time`, `update_time`) VALUES (1,'PRODUCT_MULTI_APPROVAL','\nrule \"@RULE@#1 SPU属性审批并赋值1个字段\"\n    salience 95\n    when\n        $d : DocFact( docCode == \"PRODUCT_SKU\", ext[\"@RULE@_step1_done\"] == null )\n    then\n        $d.getExt().put(\"@RULE@_step1_done\", true);\n        update($d);\n        $d.getExt().put(\"instanceId\", new java.math.BigDecimal($d.getString(\"spu.costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($d.getString(\"spu.salePrice\")).subtract(new java.math.BigDecimal($d.getString(\"spu.costPrice\"))).compareTo(new java.math.BigDecimal($d.getString(\"spu.costPrice\")).multiply(new java.math.BigDecimal(\"${marginThreshold}\"))) > 0 ? \"T+2\" : \"T\"));\n        $d.getExt().put(\"@RULE@_step1_done\", true);\n        update($d);\n        $d.addRuleMessage(\"第1步[SPU属性审批并赋值1个字段]写入 1 个返回字段\");\n    end\n\nrule \"@RULE@#2 遍历每个SKU审批并赋值2个字段\"\n    salience 90\n    when\n        $d : DocFact( docCode == \"PRODUCT_SKU\" )\n        $i : DocItem( docCode == \"PRODUCT_SKU\", collection == \"sku\" )\n        eval($i.getExt().get(\"@RULE@_step2_done\") == null)\n    then\n        $i.getExt().put(\"instanceId\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).compareTo(new java.math.BigDecimal($i.getString(\"costPrice\")).multiply(new java.math.BigDecimal(\"${marginThreshold}\"))) > 0 ? \"T+2\" : \"T\"));\n        $i.getExt().put(\"marginRate\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? null : new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).divide(new java.math.BigDecimal($i.getString(\"costPrice\")), 8, 4));\n        $i.getExt().put(\"@RULE@_step2_done\", true);\n        update($i);\n        $d.addRuleMessage(\"第2步[遍历每个SKU审批并赋值2个字段]写入 2 个返回字段\");\n    end\n\nrule \"@RULE@#3 遍历每个区域价格审批并赋值3个字段\"\n    salience 85\n    when\n        $d : DocFact( docCode == \"PRODUCT_SKU\" )\n        $i : DocItem( docCode == \"PRODUCT_SKU\", collection == \"regionPrice\" )\n        eval($i.getExt().get(\"@RULE@_step3_done\") == null)\n    then\n        $i.getExt().put(\"instanceId\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).compareTo(new java.math.BigDecimal($i.getString(\"costPrice\")).multiply(new java.math.BigDecimal(\"${marginThreshold}\"))) > 0 ? \"T+2\" : \"T\"));\n        $i.getExt().put(\"marginRate\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? null : new java.math.BigDecimal($i.getString(\"salePrice\")).subtract(new java.math.BigDecimal($i.getString(\"costPrice\"))).divide(new java.math.BigDecimal($i.getString(\"costPrice\")), 8, 4));\n        $i.getExt().put(\"priceDecision\", new java.math.BigDecimal($i.getString(\"costPrice\")).signum() <= 0 ? \"INVALID_COST\" : (new java.math.BigDecimal($i.getString(\"salePrice\")).compareTo(new java.math.BigDecimal($i.getString(\"marketPrice\"))) <= 0 ? \"STANDARD\" : \"REVIEW\"));\n        $i.getExt().put(\"@RULE@_step3_done\", true);\n        update($i);\n        $d.addRuleMessage(\"第3步[遍历每个区域价格审批并赋值3个字段]写入 3 个返回字段\");\n    end\n','2026-09-30 13:57:43','2026-09-30 13:57:43');
