subtract(new java.math.BigDecimal($i.getString(\\\"costPrice\\\"))).compareTo(new java.math.BigDecimal($i.getString(\\\"costPrice\\\")).multiply(new java.math.BigDecimal(\\\"0.3\\\"))) > 0 ? \\\"T+2\\\" : \\\"T\\\"));\\n        $i.getExt().put(\\\"marginRate\\\", new java.math.BigDecimal($i.getString(\\\"costPrice\\\")).signum() <= 0 ? null : new java.math.BigDecimal($i.getString(\\\"salePrice\\\")).subtract(new java.math.BigDecimal($i.getString(\\\"costPrice\\\"))).divide(new java.math.BigDecimal($i.getString(\\\"costPrice\\\")), 8, 4));\\n        $i.getExt().put(\\\"PRODUCT_MULTI_APPROVAL_DEFAULT_step2_done\\\", true);\\n        update($i);\\n        $d.addRuleMessage(\\\"第2步[遍历每个SKU审批并赋值2个字段]写入 2 个返回字段\\\");\\n    end\\n\\nrule \\\"PRODUCT_MULTI_APPROVAL_DEFAULT#3 遍历每个区域价格审批并赋值3个字段\\\"\\n    salience 85\\n    when\\n        $d : DocFact( docCode == \\\"PRODUCT_SKU\\\" )\\n        $i : DocItem( docCode == \\\"PRODUCT_SKU\\\", collection == \\\"regionPrice\\\" )\\n        eval($i.getExt().get(\\\"PRODUCT_MULTI_APPROVAL_DEFAULT_step3_done\\\") == null)\\n    then\\n        $i.getExt().put(\\\"instanceId\\\", new java.math.BigDecimal($i.getString(\\\"costPrice\\\")).signum() <= 0 ? \\\"INVALID_COST\\\" : (new java.math.BigDecimal($i.getString(\\\"salePrice\\\")).subtract(new java.math.BigDecimal($i.getString(\\\"costPrice\\\"))).compareTo(new java.math.BigDecimal($i.getString(\\\"costPrice\\\")).multiply(new java.math.BigDecimal(\\\"0.3\\\"))) > 0 ? \\\"T+2\\\" : \\\"T\\\"));\\n        $i.getExt().put(\\\"marginRate\\\", new java.math.BigDecimal($i.getString(\\\"costPrice\\\")).signum() <= 0 ? null : new java.math.BigDecimal($i.getString(\\\"salePrice\\\")).subtract(new java.math.BigDecimal($i.getString(\\\"costPrice\\\"))).divide(new java.math.BigDecimal($i.getString(\\\"costPrice\\\")), 8, 4));\\n        $i.getExt().put(\\\"priceDecision\\\", new java.math.BigDecimal($i.getString(\\\"costPrice\\\")).signum() <= 0 ? \\\"INVALID_COST\\\" : (new java.math.BigDecimal($i.getString(\\\"salePrice\\\")).compareTo(new java.math.BigDecimal($i.getString(\\\"marketPrice\\\"))) <= 0 ? \\\"STANDARD\\\" : \\\"REVIEW\\\"));\\n        $i.getExt().put(\\\"PRODUCT_MULTI_APPROVAL_DEFAULT_step3_done\\\", true);\\n        update($i);\\n        $d.addRuleMessage(\\\"第3步[遍历每个区域价格审批并赋值3个字段]写入 3 个返回字段\\\");\\n    end\\n\\n\"}],\"revision\":1,\"releaseId\":1,\"contentHash\":\"cba98ec94a90f99869a4a08b28e84d631e403096b79df03abcd0a8b3ce842b71\"}','cba98ec94a90f99869a4a08b28e84d631e403096b79df03abcd0a8b3ce842b71','product-seed-author','Operational rule publication','2026-09-30 06:01:45');
