i.getString(\\\"salePrice\\\")).compareTo(new java.math.BigDecimal($i.getString(\\\"marketPrice\\\"))) <= 0 ? \\\"STANDARD\\\" : \\\"REVIEW\\\"));\\n        $i.getExt().put(\\\"PRODUCT_MULTI_APPROVAL_DEFAULT_step3_done\\\", true);\\n        update($i);\\n        $d.addRuleMessage(\\\"第3步[遍历每个区域价格审批并赋值3个字段]写入 3 个返回字段\\\");\\n    end\\n\\n\"}],\"revision\":2,\"releaseId\":2,\"contentHash\":\"70759d9479082c8e3ce8e047c1cc5e32399b5da94bc7d4b563d9c1ab2b18b763\"}','70759d9479082c8e3ce8e047c1cc5e32399b5da94bc7d4b563d9c1ab2b18b763','product-seed-author','Operational rule publication','2026-09-30 06:01:48');
